**Files:**
- Create: `tablet/src/location/backgroundLocation.ts`, `tablet/src/location/usePingPoster.ts`, `tablet/src/location/usePingPoster.test.ts`, `tablet/src/location/TrackingToggle.tsx`
- Modify: `tablet/src/App.tsx` (swap the placeholder `Home` for `TrackingToggle`)
- Modify: `tablet/package.json` (add `@capacitor-community/background-geolocation`, `@testing-library/react` for the poster hook's test)

**Interfaces:** per the plan header's Interfaces summary.

- [ ] **Step 1: Install the plugin**

```bash
cd /Users/taha/Documents/atlas-fieldforce/tablet
npm install @capacitor-community/background-geolocation
npm install -D @testing-library/react jsdom
```

(`jsdom` + `@testing-library/react`'s `renderHook` needed for the same reason as the dashboard's `usePolling` test — testing a hook's timer/cleanup behavior in isolation, not a component's rendered output. Add `test: { environment: 'jsdom' }` to `vite.config.ts` if it's not already there from an earlier task.)

- [ ] **Step 2: Write `src/location/backgroundLocation.ts`**

```ts
// tablet/src/location/backgroundLocation.ts
import { registerPlugin } from '@capacitor/core'

export interface GeoLocation {
  latitude: number
  longitude: number
  accuracy: number
  time: number | null
}

interface WatcherOptions {
  backgroundMessage?: string
  backgroundTitle?: string
  requestPermissions?: boolean
  stale?: boolean
  distanceFilter?: number
}

interface BackgroundGeolocationPlugin {
  addWatcher(
    options: WatcherOptions,
    callback: (position?: GeoLocation, error?: Error) => void,
  ): Promise<string>
  removeWatcher(options: { id: string }): Promise<void>
  openSettings(): Promise<void>
}

const BackgroundGeolocation = registerPlugin<BackgroundGeolocationPlugin>('BackgroundGeolocation')

export async function startWatching(onLocation: (location: GeoLocation) => void): Promise<string> {
  return BackgroundGeolocation.addWatcher(
    {
      backgroundMessage: 'Atlas Field Force is tracking your location for field visits.',
      backgroundTitle: 'Atlas Field Force',
      requestPermissions: true,
      stale: false,
      distanceFilter: 0,
    },
    (position, error) => {
      if (error) {
        console.error('Background location error:', error)
        return
      }
      if (position) onLocation(position)
    },
  )
}

export async function stopWatching(watcherId: string): Promise<void> {
  await BackgroundGeolocation.removeWatcher({ id: watcherId })
}
```

This hand-rolls the plugin's own TypeScript interfaces (`WatcherOptions`, `GeoLocation`, `BackgroundGeolocationPlugin`) rather than importing them from `@capacitor-community/background-geolocation`'s own type exports, deliberately — its published `definitions.d.ts` exports `WatcherOptions`/`Location`/`BackgroundGeolocationPlugin` under those exact names, but `Location` collides with the DOM global `Location` type (the browser's `window.location` type), which causes confusing shadowing errors in a project that also uses the real DOM `Location` anywhere. Defining a locally-scoped `GeoLocation` alias sidesteps that collision entirely. The shapes above were copied from the installed package's real `definitions.d.ts` at plan-writing time (verified by installing the package and reading it directly, not guessed) — if `npm run typecheck` reports a mismatch against the actually-installed version, trust the installed `.d.ts` over this plan's copy and adjust minimally, don't fight it by suppressing the error.

- [ ] **Step 3: Write the failing test for `usePingPoster`**

```ts
// tablet/src/location/usePingPoster.test.ts
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { renderHook } from '@testing-library/react'
import { usePingPoster } from './usePingPoster'
import type { GeoLocation } from './backgroundLocation'

describe('usePingPoster', () => {
  beforeEach(() => vi.useFakeTimers())
  afterEach(() => vi.useRealTimers())

  it('posts the latest location on each interval tick', () => {
    const locations: GeoLocation[] = [
      { latitude: 1, longitude: 1, accuracy: 5, time: 1000 },
      { latitude: 2, longitude: 2, accuracy: 5, time: 2000 },
    ]
    let callIndex = 0
    const getLatestLocation = vi.fn(() => locations[Math.min(callIndex, locations.length - 1)])
    const onPost = vi.fn()

    renderHook(() => usePingPoster(getLatestLocation, 1000, onPost))

    vi.advanceTimersByTime(1000)
    expect(onPost).toHaveBeenCalledWith(locations[0])

    callIndex = 1
    vi.advanceTimersByTime(1000)
    expect(onPost).toHaveBeenCalledWith(locations[1])
    expect(onPost).toHaveBeenCalledTimes(2)
  })

  it('skips a tick when no location is available yet', () => {
    const getLatestLocation = vi.fn(() => null)
    const onPost = vi.fn()

    renderHook(() => usePingPoster(getLatestLocation, 1000, onPost))

    vi.advanceTimersByTime(1000)
    expect(onPost).not.toHaveBeenCalled()
  })

  it('stops posting after unmount', () => {
    const getLatestLocation = vi.fn(() => ({ latitude: 1, longitude: 1, accuracy: 5, time: 1000 }))
    const onPost = vi.fn()

    const { unmount } = renderHook(() => usePingPoster(getLatestLocation, 1000, onPost))
    unmount()

    vi.advanceTimersByTime(5000)
    expect(onPost).not.toHaveBeenCalled()
  })
})
```

(This test's `usePingPoster` signature takes an explicit `onPost` callback rather than calling `submitPing` directly, so the test can assert on posted values without mocking `fetch` — the real `TrackingToggle` component in Step 5 supplies `onPost` as a function that calls `submitPing` with a freshly generated idempotency key.)

- [ ] **Step 4: Write `src/location/usePingPoster.ts`**

```ts
// tablet/src/location/usePingPoster.ts
import { useEffect, useRef } from 'react'
import type { GeoLocation } from './backgroundLocation'

export function usePingPoster(
  getLatestLocation: () => GeoLocation | null,
  intervalMs: number,
  onPost: (location: GeoLocation) => void,
): void {
  const getLatestLocationRef = useRef(getLatestLocation)
  getLatestLocationRef.current = getLatestLocation
  const onPostRef = useRef(onPost)
  onPostRef.current = onPost

  useEffect(() => {
    const id = setInterval(() => {
      const location = getLatestLocationRef.current()
      if (location) onPostRef.current(location)
    }, intervalMs)
    return () => clearInterval(id)
  }, [intervalMs])
}
```

